    /** A social title as stored ("LinkedIn", "x", "Twitter") to an icon key; null when there is no icon for it */
    public static function key(string $title): ?string
    {
        $key = strtolower(preg_replace('/[^a-z]/i', '', $title));
        $key = ['twitter' => 'x', 'buymeacoffee' => 'coffee', 'mail' => 'contact', 'email' => 'contact'][$key] ?? $key;

        return isset(self::PATHS[$key]) ? $key : null;
    }

    /** Inline SVG for a key (decorative: the link carries the name in aria-label) */
    public static function svg(?string $key): string
    {
        $path = self::PATHS[$key ?? ''] ?? null;
        if ($path === null) {
            return '';
        }

        return '<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="' . $path . '"/></svg>';
    }
